// Parallel Thai display content. Original case JSON owns targets, lab numbers,
// correct-choice indices and weights; language changes never modify those fields.
window.BIOCHEM_CASES_TH = {};
function addThaiCase(file, data) {
  const prompts = data.prompts;
  const feedback = data.feedback;
  data.explain = {prompts:{diagnosis:prompts[0],cause:prompts[1],mechanism:prompts[2]}};
  data.pinpoint = {prompt:feedback[0],correctMsg:feedback[1],wrongMsg:feedback[2],revealMsg:feedback[3]};
  data.mcqs = data.questions.map(q => ({stem:q[0],choices:q[1],explanation:q[2]}));
  delete data.prompts; delete data.feedback; delete data.questions;
  BIOCHEM_CASES_TH[file] = data;
}
